<script setup lang="ts">
import {onMounted, ref, watch} from 'vue'
import {ArrowRight, Check, KeyRound, Plus, ShieldCheck, UsersRound} from 'lucide-vue-next'
import {request} from '../api'
import type {Account} from '../types'
type User = {id:string; username:string; role:string; disabled:boolean}
const props=defineProps<{user:{id:string;username:string;role:string};accounts:Account[];demo:boolean;mode:'users'|'accounts'|'password'}>()
const emit=defineEmits<{refresh:[];signedOut:[]}>()
const users=ref<User[]>([]),error=ref(''),message=ref(''),busy=ref(false)
const newUser=ref({username:'',password:'',role:'member'})
const account=ref({name:'',role:'secondary',owner_id:props.user.id})
const password=ref({current_password:'',new_password:'',confirm:''})
const resetID=ref(''),resetValue=ref('')
const owners=ref<Record<string,string>>({}),names=ref<Record<string,string>>({})
async function load(){if(props.user.role==='admin'&&!props.demo)users.value=await request<User[]>('/users');else if(props.demo)users.value=[{...props.user,disabled:false}];for(const a of props.accounts){owners.value[a.id]=a.owner_id||props.user.id;names.value[a.id]=a.name}}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{if(props.demo){message.value='演示模式不保存用户或修改密码。';return}await action()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function createUser(){await run(async()=>{await request('/users',{method:'POST',body:JSON.stringify(newUser.value)});newUser.value={username:'',password:'',role:'member'};await load();message.value='用户已创建，可使用设置的密码登录。请通过私密渠道交付密码。'})}
async function updateUser(u:User,patch:Partial<User>&{password?:string}){await run(async()=>{await request(`/users/${u.id}`,{method:'PUT',body:JSON.stringify({...u,...patch})});resetValue.value='';resetID.value='';await load();message.value='用户设置已保存。权限或密码变化后，原登录会立即失效。'})}
async function createAccount(){await run(async()=>{await request('/accounts',{method:'POST',body:JSON.stringify(account.value)});account.value.name='';emit('refresh');message.value=props.user.role==='admin'?'账号记录已添加，请在账号详情中绑定已发现的 MAA 配置档。':'账号记录已添加，等待管理员绑定 MAA 配置档。'})}
async function updateAccount(a:Account){await run(async()=>{await request(`/accounts/${a.id}`,{method:'PUT',body:JSON.stringify({name:names.value[a.id]||a.name,owner_id:owners.value[a.id]||a.owner_id})});emit('refresh');message.value='账号归属与名称已保存，原配置保持不变。'})}
async function changePassword(){if(password.value.new_password!==password.value.confirm){error.value='两次新密码输入不一致';return}await run(async()=>{await request('/auth/password',{method:'POST',body:JSON.stringify(password.value)});password.value={current_password:'',new_password:'',confirm:''};emit('signedOut')})}
watch(()=>props.accounts,()=>{for(const a of props.accounts){if(owners.value[a.id]===undefined)owners.value[a.id]=a.owner_id||props.user.id;if(names.value[a.id]===undefined)names.value[a.id]=a.name}})
onMounted(()=>{load().catch(e=>error.value=e.message)})
</script>
<template>
<div class="user-workspace">
<p v-if="error" class="inline-alert" role="alert">{{error}}</p><p v-if="message" class="agent-feedback" role="status"><Check :size="16"/>{{message}}</p>
<section v-if="mode==='password'" class="panel user-password"><div class="panel-heading"><div><span class="eyebrow">// YOUR ACCESS</span><h2>修改登录密码</h2></div><KeyRound :size="22"/></div><p class="muted">当前用户：{{user.username}} · {{user.role==='admin'?'管理员':'成员'}}。改密成功后需要重新登录。</p><form @submit.prevent="changePassword"><label>当前密码<input type="password" v-model="password.current_password" autocomplete="current-password" required/></label><label>新密码<input type="password" v-model="password.new_password" autocomplete="new-password" minlength="12" maxlength="72" required placeholder="12–72 字节，建议使用独立长密码"/></label><label>再次输入新密码<input type="password" v-model="password.confirm" autocomplete="new-password" minlength="12" maxlength="72" required/></label><button class="button primary" :disabled="busy">保存新密码<ArrowRight :size="16"/></button></form></section>
<template v-else-if="mode==='users'&&user.role==='admin'">
<div class="agent-intro"><UsersRound :size="32"/><div><span class="eyebrow">// SHARE THE ROUTINE</span><h2>各管各的账号，一起省点心。</h2><p>创建登录用户，再把对应的 MAA 账号分配给他。成员只能查看和调整自己的账号。</p></div></div>
<div class="user-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">01 / INVITE</span><h2>添加用户</h2></div><Plus :size="20"/></div><form @submit.prevent="createUser"><label>用户名<input v-model="newUser.username" autocomplete="off" pattern="[A-Za-z0-9][A-Za-z0-9_.\-]{2,47}" required placeholder="3–48 位字母、数字或 . _ -"/></label><label>初始密码<input type="password" v-model="newUser.password" autocomplete="new-password" minlength="12" maxlength="72" required/></label><label>权限<select v-model="newUser.role"><option value="member">成员 · 管理自己的账号</option><option value="admin">管理员 · 管理所有账号与用户</option></select></label><button class="button primary" :disabled="busy">创建用户<ArrowRight :size="16"/></button></form><p class="muted">不开放自行注册。成员登录后可在系统设置中修改自己的密码；模型接入与通知设置分别保存。</p></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">02 / MANAGE ACCESS</span><h2>已有用户 <small>{{users.length}}</small></h2></div><ShieldCheck :size="20"/></div><div class="user-row" v-for="u in users" :key="u.id"><div class="user-row-heading"><strong>{{u.username}} <small v-if="u.id===user.id">当前用户</small></strong><span class="agent-chip">{{u.disabled?'已停用':u.role==='admin'?'管理员':'成员'}}</span></div><p class="muted">名下账号 {{accounts.filter(a=>a.owner_id===u.id||(!a.owner_id&&u.id===user.id)).length}} 个</p><div class="agent-button-row"><button class="button small" v-if="u.id!==user.id" :disabled="busy" @click="updateUser(u,{disabled:!u.disabled})">{{u.disabled?'启用用户':'停用用户'}}</button><button class="button small" v-if="u.id!==user.id" :disabled="busy" @click="updateUser(u,{role:u.role==='admin'?'member':'admin'})">{{u.role==='admin'?'设为成员':'设为管理员'}}</button><button class="text-button" v-if="u.id!==user.id" @click="resetID=u.id;resetValue=''">重置密码</button><span v-else class="muted">自己的密码请在系统设置修改</span></div><form v-if="resetID===u.id" class="user-reset" @submit.prevent="updateUser(u,{password:resetValue})"><label>为此用户设置新密码<input type="password" v-model="resetValue" autocomplete="new-password" required minlength="12" maxlength="72"/></label><div class="agent-button-row"><button type="button" class="button" @click="resetID='';resetValue=''">取消</button><button class="button primary" :disabled="busy">确认重置并退出原登录</button></div></form></div></section></div>
</template>
<template v-else-if="mode==='accounts'">
<div class="user-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">// ADD AN ACCOUNT</span><h2>添加 MAA 账号</h2></div><Plus :size="20"/></div><form @submit.prevent="createAccount"><label>账号名称<input v-model="account.name" maxlength="120" required placeholder="给账号起个容易识别的名字"/></label><label>资源策略<select v-model="account.role"><option value="secondary">副号 · 普通药 0 / 源石 0 / 临期 48h</option><option value="primary">主号 · 保留独立资源设置</option></select></label><label v-if="user.role==='admin'">所属用户<select v-model="account.owner_id"><option v-for="u in users.filter(u=>!u.disabled)" :value="u.id" :key="u.id">{{u.username}}</option></select></label><p class="muted">添加后由管理员绑定已发现的配置档。一个配置档只能绑定一个账号。</p><button class="button primary" :disabled="busy">添加账号<ArrowRight :size="16"/></button></form></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">// ACCOUNT OWNERSHIP</span><h2>{{user.role==='admin'?'账号分配':'我的账号'}}</h2></div><UsersRound :size="20"/></div><p class="muted" v-if="!accounts.length">还没有账号。可以先添加账号记录，再请管理员完成绑定。</p><form class="user-row" v-for="a in accounts" :key="a.id" @submit.prevent="updateAccount(a)"><label>账号名称<input v-model="names[a.id]" :placeholder="a.name" maxlength="120" required/></label><label v-if="user.role==='admin'">所属用户<select v-model="owners[a.id]"><option v-for="u in users" :key="u.id" :value="u.id" :disabled="u.disabled">{{u.username}}{{u.disabled?'（已停用）':''}}</option></select></label><p class="muted">{{a.profile?.name||'等待管理员绑定配置档'}} · {{a.role==='secondary'?'副号':'主号'}}</p><button class="button small" :disabled="busy">保存{{user.role==='admin'?'分配与名称':'名称'}}</button></form></section></div>
</template>
</div>
</template>
<style scoped>
.user-workspace{margin-bottom:28px;--line:var(--ef-rule);--surface:var(--ef-panel);--bg:var(--ef-paper);--muted:var(--ef-ink-2);--text:var(--ef-ink)}.user-workspace .panel{border:1px solid var(--ef-rule);background:var(--ef-panel);min-width:0}.user-workspace .panel-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:18px;margin-bottom:22px;border-bottom:1px solid var(--ef-rule)}.user-workspace .panel-heading h2{margin-top:5px}.user-grid{display:grid;grid-template-columns:minmax(280px,.8fr) minmax(320px,1.2fr);gap:24px;margin:24px 0}.user-grid>.panel,.user-password{padding:28px}.user-workspace form{display:grid;gap:18px}.user-row{padding:22px 0;border-top:1px solid var(--ef-rule)}.user-row-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.user-row small{font-weight:400;font-size:12px}.user-row .muted{margin:12px 0}.user-password{max-width:720px;margin-top:24px}.user-password form{margin-top:24px}.user-reset{margin-top:18px;padding:18px;border:1px solid var(--ef-rule)}.user-workspace input,.user-workspace select{width:100%;min-height:42px;padding:10px 12px;border:1px solid var(--ef-rule);background:var(--ef-paper);color:var(--ef-ink);border-radius:0}.user-workspace label{display:grid;gap:8px;font-size:12px;font-weight:500}.user-workspace label{min-width:0}.user-workspace .button{justify-self:start}.user-workspace .agent-intro{gap:20px}@media(max-width:900px){.user-grid{grid-template-columns:1fr}.user-grid>.panel,.user-password{padding:20px}.user-workspace .agent-intro{align-items:flex-start}}
</style>
